insert into public.football_team_profiles (team_id, nickname, tags, intro) values
(1899, null, '{그리스 아테네,오파프 아레나,1924년 창단}', $t$<p>AEK 아테네는 그리스 수도 아테네를 연고로 하는 구단으로, 1922년 소아시아 전쟁 이후 콘스탄티노플에서 건너온 그리스 난민들이 세웠습니다. 구단 엠블럼의 쌍두독수리는 비잔티움 제국에 뿌리를 둔 이런 역사를 상징합니다. 그리스 리그에서 올림피아코스, 파나티나이코스와 함께 전통의 강호로 꼽히며, 2022년 문을 연 새 홈구장 오파프 아레나는 열정적인 응원으로 유명합니다.</p><p>토리코리 관전 포인트: 토리코리는 AEK의 그리스 리그 경기는 다루지 않고 챔피언스리그 경기만 집계하므로, 표본이 적다는 점을 감안해 숫자를 읽어야 합니다. 뜨거운 홈 분위기가 결과로 이어지는지 홈·원정 성적을 나눠 보고, 최근 5경기 흐름을 함께 확인해 보세요.</p>$t$),
(2016, null, '{오스트리아 린츠,라이파이젠 아레나,1908년 창단}', $t$<p>LASK 린츠는 오스트리아 북부 도시 린츠를 연고로 하는 구단입니다. 1965년 빈 이외 지역 구단으로는 처음으로 오스트리아 리그 정상에 오르며 컵 대회까지 함께 차지했습니다. 오랫동안 빈의 명문 구단들과 잘츠부르크 사이에서 도전자 역할을 해 왔고, 2023년 옛 린츠 경기장 자리에 새 홈구장 라이파이젠 아레나를 열었습니다.</p><p>토리코리 관전 포인트: 토리코리에는 LASK의 오스트리아 리그 기록이 없고 챔피언스리그 경기만 쌓이기 때문에, 경기 수가 적은 시점에는 경기당 승점 하나로 판단하지 않는 편이 좋습니다. 강팀을 상대로 버티는 경기가 많은 만큼 무실점 비율과 2.5골 오버 비율을 함께 보면 경기 성향을 가늠할 수 있습니다.</p>$t$),
(610, '짐봄', '{튀르키예 이스탄불,람스 파크,1905년 창단}', $t$<p>갈라타사라이는 1905년 이스탄불의 갈라타사라이 고등학교 학생들이 만든 구단으로, 튀르키예 리그 최다 우승을 자랑하는 명문입니다. 2000년 결승에서 아스널을 승부차기로 꺾고 UEFA컵을 들어 올려 튀르키예 구단 최초로 유럽 대항전 정상에 올랐고, 같은 해 UEFA 슈퍼컵에서 레알 마드리드까지 꺾었습니다. 유럽 쪽에 뿌리를 둔 갈라타사라이와 아시아 쪽 카드쾨이의 페네르바흐체가 맞붙는 경기는 "대륙 간 더비"로 불립니다.</p><p>토리코리 관전 포인트: 원정팀에게 악명 높은 홈 분위기 덕분에 갈라타사라이는 홈과 원정 성적 차이가 크게 벌어지는 경우가 많습니다. 토리코리는 챔피언스리그 경기만 집계하므로, 홈·원정 성적을 나눠 보고 최근 5경기 흐름으로 기세를 확인해 보세요.</p>$t$),
(5720, null, '{노르웨이 스타방에르,바이킹 스타디온,1899년 창단}', $t$<p>바이킹은 노르웨이 서남부 항구 도시 스타방에르를 연고로 하는 구단으로, 노르웨이에서 가장 오래된 축구 구단 가운데 하나입니다. 1970년대에 리그를 연이어 제패하는 등 노르웨이 리그 우승을 여러 차례 차지한 전통의 강호입니다. 2004년 문을 연 바이킹 스타디온을 홈으로 쓰며, 지역 팬들의 충성도가 높은 구단으로 알려져 있습니다.</p><p>토리코리 관전 포인트: 토리코리는 바이킹의 노르웨이 리그 경기는 다루지 않고 챔피언스리그 경기만 기록하므로, 시즌 초반 숫자는 몇 경기 결과에 크게 흔들릴 수 있습니다. 경기당 승점과 무실점 비율을 함께 보면서 유럽 무대에서 수비가 얼마나 버티는지 살펴보세요.</p>$t$),
(5721, null, '{노르웨이 보되,아스뮈라 스타디온,1916년 창단}', $t$<p>보되/글림트는 북극권 바로 위에 있는 인구 5만 명 남짓의 작은 도시 보되를 연고로 하는 구단입니다. 2020년 첫 노르웨이 리그 우승을 차지한 뒤 짧은 기간에 여러 차례 정상에 오르며 노르웨이 축구의 새 강자로 떠올랐습니다. 2021년 콘퍼런스리그에서 AS 로마를 6대1로 꺾어 화제가 됐고, 2025년에는 유로파리그 4강까지 올랐습니다. 추운 기후 탓에 인조잔디를 깐 아스뮈라 스타디온을 홈으로 씁니다.</p><p>토리코리 관전 포인트: 인조잔디와 북극권의 추위는 원정팀에게 낯선 조건이라, 보되/글림트는 홈·원정 성적 차이를 꼭 나눠 봐야 하는 팀입니다. 토리코리에는 챔피언스리그 경기만 쌓이므로 2.5골 오버 비율과 최근 5경기 흐름을 함께 보며 공격적인 성향이 유럽 무대에서도 통하는지 확인해 보세요.</p>$t$),
(10233, null, '{아제르바이잔 바쿠,방크 레스푸블리카 아레나,2017년 창단}', $t$<p>사바흐는 아제르바이잔 수도 바쿠를 연고로 2017년에 창단한 신생 구단입니다. 창단 직후 아제르바이잔 1부 리그에 참가했고, 짧은 역사에도 리그 상위권 경쟁에 꾸준히 이름을 올리며 유럽 대항전 무대를 밟고 있습니다.</p><p>토리코리 관전 포인트: 토리코리는 사바흐의 아제르바이잔 리그 경기를 다루지 않고 챔피언스리그 경기만 집계하므로, 경기 수가 적을 때는 숫자를 참고 정도로만 보는 것이 좋습니다. 경기당 승점과 무실점 비율을 함께 보면 유럽 무대에서의 경쟁력을 가늠할 수 있습니다.</p>$t$),
(1887, '히르니키', '{우크라이나 도네츠크,돈바스 아레나,1936년 창단}', $t$<p>샤흐타르 도네츠크는 우크라이나 동부 탄광 도시 도네츠크에서 광부들의 팀으로 출발했고, "히르니키(광부들)"라는 별명도 여기서 나왔습니다. 2000년대 이후 디나모 키이우와 함께 우크라이나 리그를 양분했으며, 2009년 결승에서 베르더 브레멘을 꺾고 UEFA컵을 들어 올렸습니다. 2014년 돈바스 지역 분쟁 이후 홈구장 돈바스 아레나를 쓰지 못하고 우크라이나의 다른 도시나 해외 경기장을 빌려 홈경기를 치르고 있습니다.</p><p>토리코리 관전 포인트: 오랫동안 연고지를 떠나 경기를 치러 온 만큼, 샤흐타르의 홈 경기는 다른 팀의 홈 경기와 같은 이점을 기대하기 어렵습니다. 토리코리는 챔피언스리그 경기만 집계하므로 홈·원정 성적 차이가 얼마나 작은지, 경기당 승점이 어느 수준인지 함께 살펴보세요.</p>$t$),
(930, '세시바니', '{체코 프라하,에덴 아레나,1892년 창단}', $t$<p>슬라비아 프라하는 체코 수도 프라하를 연고로 하는 구단으로, 체코에서 가장 오래된 축구 구단 가운데 하나입니다. 빨강과 하양을 반씩 이어 붙인 유니폼에서 "세시바니(꿰맨 사람들)"라는 별명이 나왔고, 가슴의 붉은 별도 구단의 상징입니다. 같은 도시의 스파르타 프라하와 치르는 프라하 더비는 체코 최대의 라이벌전으로 꼽히며, 1995-96 시즌에는 UEFA컵 4강에 오르기도 했습니다.</p><p>토리코리 관전 포인트: 토리코리에는 슬라비아의 체코 리그 기록이 없고 챔피언스리그 경기만 남기 때문에, 시즌 중간에는 표본이 적다는 점을 기억해야 합니다. 더비처럼 거친 경기에 익숙한 팀이 유럽 무대에서 어떤 양상을 보이는지 무실점 비율과 2.5골 오버 비율을 나란히 놓고 보면 경기 양상을 예상하기 쉽습니다.</p>$t$),
(7509, '벨라시', '{슬로바키아 브라티슬라바,테헬네 폴레,1919년 창단}', $t$<p>슬로반 브라티슬라바는 슬로바키아 수도 브라티슬라바를 연고로 하는 구단으로, 슬로바키아 리그 최다 우승을 자랑합니다. 하늘색 유니폼에서 "벨라시(하늘색 팀)"라는 별명이 나왔습니다. 1969년 컵위너스컵 결승에서 바르셀로나를 3대2로 꺾고 우승해, 체코슬로바키아 시절을 통틀어 유럽 대항전 정상에 오른 유일한 구단이 됐습니다. 국가대표팀 경기장으로도 쓰이는 테헬네 폴레를 홈으로 씁니다.</p><p>토리코리 관전 포인트: 토리코리는 슬로반의 슬로바키아 리그 경기는 다루지 않고 챔피언스리그 경기만 집계합니다. 국내 리그에서와 달리 유럽 무대에서는 수비적으로 나서는 경기가 많을 수 있으니, 경기당 승점과 최근 5경기 결과를 함께 보며 흐름을 읽어 보세요.</p>$t$),
(851, null, '{벨기에 브뤼허,얀 브레이델 스타디온,1891년 창단}', $t$<p>클뤼프 브뤼허는 벨기에 북서부의 옛 도시 브뤼허를 연고로 하는 구단으로, 안데를레흐트와 함께 벨기에 축구를 대표하는 명문입니다. 1978년 유러피언컵 결승에 올라 리버풀에 졌지만, 지금까지도 이 대회 결승에 오른 유일한 벨기에 구단으로 남아 있습니다. 같은 도시의 세르클러 브뤼허와 얀 브레이델 스타디온을 함께 쓰며, 두 팀의 브뤼허 더비도 유명합니다.</p><p>토리코리 관전 포인트: 브뤼허는 챔피언스리그 조별 단계에서 꾸준히 경쟁력을 보여 온 팀이라, 토리코리의 경기당 승점과 홈·원정 성적을 비교하면 홈에서 얼마나 강한지가 잘 드러납니다. 토리코리는 벨기에 리그 경기는 집계하지 않으므로 최근 5경기 흐름도 챔피언스리그 경기 기준이라는 점을 기억하세요.</p>$t$),
(613, '카나리아', '{튀르키예 이스탄불,쉬크뤼 사라졸루 스타디움,1907년 창단}', $t$<p>페네르바흐체는 이스탄불의 아시아 쪽 지역인 카드쾨이를 연고로 하는 구단으로, 노란색과 남색 유니폼 때문에 "노란 카나리아"라는 별명으로 불립니다. 갈라타사라이, 베식타시와 함께 이스탄불의 3대 명문으로 꼽히며, 유럽 쪽의 갈라타사라이와 맞붙는 "대륙 간 더비"는 세계에서 가장 뜨거운 라이벌전 가운데 하나입니다. 한국 수비수 김민재가 2021-22 시즌 이곳에서 뛰며 유럽 무대에 이름을 알렸습니다.</p><p>토리코리 관전 포인트: 쉬크뤼 사라졸루 스타디움의 응원은 원정팀에게 큰 부담이 되는 만큼, 페네르바흐체는 홈·원정 성적을 나눠 보는 것이 기본입니다. 토리코리는 챔피언스리그 경기만 집계하므로 2.5골 오버 비율과 무실점 비율로 경기 성향을 함께 확인해 보세요.</p>$t$)
